validator:
function validate(input) {
  const [{ students = [], courses = [], enrollments = [] }] = input;
  const people = new Set(), offered = new Set(), majors = new Set(), taken = new Set();
  for (const [id] of students) {
    if (id === null) return 'Every student needs a student_id.';
    if (people.has(id)) return `student_id ${id} appears twice in students.`;
    people.add(id);
  }
  for (const [id, , , major] of courses) {
    if (id === null) return 'Every course needs a course_id.';
    if (offered.has(id)) return `course_id ${id} appears twice in courses.`;
    offered.add(id);
    if (typeof major === 'string') majors.add(major.toLowerCase());
  }
  for (const [id, , major] of students) {
    if (typeof major !== 'string' || !majors.has(major.toLowerCase())) return `Student ${id}'s major offers no course.`;
  }
  for (const [student, course, , grade] of enrollments) {
    if (!people.has(student)) return `Enrollment names student ${student}, who is not in students.`;
    if (!offered.has(course)) return `Enrollment names course ${course}, which is not in courses.`;
    const key = `${student}/${course}`;
    if (taken.has(key)) return `Student ${student} takes course ${course} twice.`;
    taken.add(key);
    if (!['A', 'B', 'C', 'D', 'F'].includes(grade)) return `Grade ${grade} must be one of A, B, C, D, F.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const allMajors = ['Computer Science', 'Mathematics', 'Physics', 'Biology', 'Chemistry', 'History'];
  const titles = ['Algorithms', 'Calculus', 'Mechanics', 'Genetics', 'Statistics', 'Optics', 'Databases', 'Ecology', 'Topology', 'Networks'];
  const names = ['Alice', 'Bob', 'Charlie', 'David', 'Eve', 'Frank', 'Grace', 'Heidi'];
  const semesters = ['Fall 2023', 'Spring 2023', 'Fall 2022', 'Spring 2024'];
  const majorCount = small ? 1 + Math.floor(rand() * 3) : 6;
  const majors = allMajors.slice(0, majorCount);
  const courses = [], byMajor = {};
  let courseId = 100;
  for (const major of majors) {
    byMajor[major] = [];
    const count = small ? 1 + Math.floor(rand() * 2) : 3 + Math.floor(rand() * 6);
    for (let i = 0; i < count; i++) {
      courseId += 1 + Math.floor(rand() * 2);
      courses.push([courseId, pick(titles), pick([2, 3, 4]), major]);
      byMajor[major].push(courseId);
    }
  }
  const studentCount = small ? Math.floor(rand() * 5) : 220;
  const students = [], enrollments = [];
  for (let id = 1; id <= studentCount; id++) {
    const major = pick(majors);
    students.push([id, pick(names), major]);
    // Some students are strong and ace every course of their major; the rest miss courses or grades.
    const strong = rand() < 0.4;
    for (const course of byMajor[major]) {
      if (!strong && rand() < 0.2) continue;
      const grade = strong || rand() < 0.65 ? 'A' : pick(['B', 'C', 'D', 'F']);
      enrollments.push([id, course, pick(semesters), grade]);
    }
    // Courses outside the major, with any grade, must not change the answer.
    const others = courses.filter(c => c[3] !== major);
    if (others.length && rand() < 0.4) enrollments.push([id, pick(others)[0], pick(semesters), pick(['A', 'B', 'C', 'F'])]);
  }
  for (const rows of [students, enrollments]) for (let i = rows.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [rows[i], rows[j]] = [rows[j], rows[i]];
  }
  return [{ students, courses, enrollments }];
}
